    window.addEventListener("unhandledrejection",function(event){rememberRuntimeError(event.reason)});
    function reportRuntimeSmoke(){if(window.parent===window)return;var hasRuntime=Boolean(root&&root.children.length&&!root.querySelector(".empty"));var hasDropsBot=Boolean(document.querySelector('[data-action="dropsbot"],[data-action="dropsbot-setup"]'));var hasUnsafeExecution=Boolean(document.querySelector('[data-action="execute-trade"],[data-action="auto-trade"]'));postParent({type:"drops-studio-runtime-smoke",slug:spec.slug,result:{executed:true,runtime:hasRuntime,interactions:runtimeHandlersReady&&interactionProbePassed,dropstab:dataAdapterCompleted,dropsbot:hasDropsBot&&actionProbePassed,actions:actionProbePassed&&!hasUnsafeExecution,mode:"browser",dataProvider:dataProvider,errors:runtimeErrors.slice(),checkedAt:new Date().toISOString()}})}
    function runRuntimeProbes(){var probe=document.querySelector('[data-action="dropsbot-setup"]');if(!probe)return reportRuntimeSmoke();try{probe.dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true}));var modal=document.getElementById("integrationModal");interactionProbePassed=Boolean(modal);actionProbePassed=Boolean(modal&&modal.querySelector('[data-studio-telegram="true"]')&&modal.querySelector('[data-action="telegram-verify"]')&&/MTProto/.test(modal.textContent||""));if(modal)closeIntegration(false)}catch(error){rememberRuntimeError(error)}reportRuntimeSmoke()}
