    function change(value){if(!available(value))return '<span class="muted">—</span>';var number=Number(value);return '<span class="'+(number>=0?'positive':'negative')+'">'+(number>=0?'+':'')+number.toFixed(2)+'%</span>'}
    function movement(value){if(!available(value))return "change is unavailable";var number=Number(value);return (number>=0?"up ":"down ")+Math.abs(number).toFixed(2)+"%"}
