    function dropsbotSetup(){var existing=document.getElementById("integrationModal");if(existing)existing.remove();var recipe=(spec.blueprint&&spec.blueprint.dropsBotUse||[]).join("\\n");var defaultMessage=(state.posts&&state.posts[0]&&state.posts[0].copy)||((spec.blueprint&&spec.blueprint.content&&spec.blueprint.content.headline)||spec.name)+"\\n\\nBuilt from DropsTab market context. Verify the full research trail before acting.\\nhttps://dropstab.com/";var modal=document.createElement("div");modal.className="integration-modal";modal.id="integrationModal";modal.innerHTML='<section class="integration-card"><span class="eyebrow">VERIFIED TELEGRAM SETUP</span><h2>Create a new channel in Studio, or verify one you already own</h2><p>The Telegram phone below is a preview only. For a new destination, Drops Studio first connects your Telegram user account through its existing MTProto wizard; the external action happens only after your explicit approval.</p><div class="integration-options"><article class="integration-option"><span class="eyebrow">OPTION A · NEW CHANNEL VIA STUDIO</span><h3>Connect the user account, then add the selected Telegram bot</h3><div class="integration-steps"><div><b>1</b><span><strong>Connect through MTProto</strong><small>Open the secure Studio wizard, enter the code sent by Telegram and an optional two-step password, and keep the account session outside this export.</small></span></div><div><b>2</b><span><strong>Approve the real destination</strong><small>Create or select the channel only after reviewing its title, description and first post.</small></span></div><div><b>3</b><span><strong>Add the selected Telegram bot</strong><small>Grant the selected bot administrator permission and verify delivery from Telegram. Link an official Drops Bot Profile separately with /profiles and /use_thread.</small></span></div></div><div class="button-row"><a class="primary integration-link" data-studio-telegram="true" href="'+esc(studioTelegramUrl)+'" target="_blank" rel="noreferrer" aria-label="Open Studio Telegram connection in a new tab">Open Studio Telegram connection</a><button class="ghost" data-action="open-official-bot" aria-label="Open official Drops Bot in Telegram">Open official Drops Bot</button><button class="ghost" data-action="copy-recipe">Copy recipe</button></div><div class="integration-note">Drops Bot setup recipe: '+esc(recipe||"Price, wallet and event alerts with Telegram delivery")+'. Opening or copying it does not prove that an official Drops Bot Profile is configured. This export receives no MTProto credentials and never treats its preview as proof of a channel.</div></article><article class="integration-option"><span class="eyebrow">OPTION B · EXISTING CHANNEL FALLBACK</span><h3>Verify and send with your bot</h3><label>BotFather token · session-only<input id="tgToken" type="password" autocomplete="off" placeholder="123456789:AA…"></label><label>Existing channel you own<input id="tgChannel" autocomplete="off" placeholder="@channelusername or -100…"></label><label>Test post<textarea id="tgMessage">'+esc(defaultMessage)+'</textarea></label><div class="button-row"><button class="ghost" data-action="telegram-verify">Verify bot + channel</button><button class="primary" data-action="telegram-send">Send verified test post</button></div><div class="integration-note">The token is sent over HTTPS only to the current app origin. It is never written to project state, localStorage, publish history or ZIP. Success requires Telegram to return the channel identity and bot administrator status.</div><div class="integration-status" id="telegramStatus">Waiting for a BotFather token and an existing channel.</div></article></div><div class="button-row"><button class="ghost" data-action="close-integration">Close</button></div></section>';document.body.appendChild(modal)}
    var renderDropsbotSetup=dropsbotSetup;
