    function teardownIntegration(restoreFocus){document.removeEventListener("keydown",integrationModalKeydown,true);if(integrationObserver){integrationObserver.disconnect();integrationObserver=null}var trigger=integrationTrigger;integrationTrigger=null;if(restoreFocus!==false&&trigger&&trigger.isConnected&&typeof trigger.focus==="function")requestAnimationFrame(function(){trigger.focus()})}
