    var nativeRuntimeTitles={"action-engine":"Decision system recipe","alpha-channel":"Channel operating model","morning-alpha":"Brief production recipe","prediction-impact":"Prediction research workflow","smart-money-copy":"Copy strategy guardrails","crypto-aggregator":"Aggregator product contract","crypto-game":"Game rules and distribution","personal-companion":"Personalization contract","portfolio-tamagotchi":"Portfolio care model","crypto-product-hunt":"Discovery board rules","crypto-radio":"Audio production recipe","crypto-siri":"Assistant response contract","custom-product":"Custom product contract"};
