    function gameMarket(){var scope=String(spec.values.assets||"").toLowerCase();var rows=market.slice();if(scope.indexOf("solana")>=0)rows=rows.filter(function(coin){return ["SOL","JUP","JTO","RAY","BONK","WIF"].indexOf(String(coin.symbol||"").toUpperCase())>=0});if(scope.indexOf("meme")>=0)rows=rows.filter(function(coin){return ["DOGE","SHIB","PEPE","BONK","WIF"].indexOf(String(coin.symbol||"").toUpperCase())>=0});return (rows.length?rows:market).slice(0,5)}
