    function renderMarketRaceGame(){var content=spec.blueprint&&spec.blueprint.content||{};var rows=gameMarket().slice(0,3);var max=Math.max.apply(null,rows.map(function(coin){return Math.abs(n(coin.change))}).concat([1]));var lanes=rows.map(function(coin,index){var progress=Math.max(16,Math.round(Math.abs(n(coin.change))/max*82));if(state.gameRaceWinner===coin.symbol)progress=96;return '<div class="game-race-lane"><b>'+esc(coin.symbol||"—")+'</b><i style="--progress:'+progress+'%"></i><span>'+change(coin.change)+'</span></div>'}).join("");var result=state.lastResult?'<div class="game-native-result"><strong>Race result:</strong> '+esc(state.lastResult)+' · saved in this browser</div>':'';root.innerHTML=gameFrame('market-race',content.headline||"Beat the Market",content.subheadline||"Choose a live-market racer and run a local momentum round.",'<main class="game-native-board"><h3>Which asset leads this market snapshot?</h3><p>The race uses the available percentage-change snapshot. It never places a trade and does not invent missing data.</p><div class="game-race-lanes">'+lanes+'</div>'+result+'<div class="game-native-actions"><button class="primary" data-action="start-market-race">Run market race</button><button class="ghost" data-action="refresh">Refresh snapshot</button></div></main>')}
    function renderCoinQuizGame(){var content=spec.blueprint&&spec.blueprint.content||{};var rows=gameMarket().slice(0,3);var target=rows[n(state.gameQuizIndex)%Math.max(1,rows.length)]||{};var choices=rows.map(function(coin){var active=state.gameQuizChoice===coin.symbol;return '<button class="game-choice '+(active?'active':'')+'" data-quiz-choice="'+esc(coin.symbol)+'"><span>Choose asset</span><strong>'+esc(coin.symbol)+'</strong><small>'+esc(coin.name||"Tracked asset")+'</small></button>'}).join("");var result=state.lastResult?'<div class="game-native-result"><strong>Quiz result:</strong> '+esc(state.lastResult)+'</div>':'';root.innerHTML=gameFrame('coin-quiz',content.headline||"Guess the Coin",content.subheadline||"Read a sourced market clue and identify the asset.",'<main class="game-native-board"><h3>Which coin matches this market clue?</h3><p>Rank '+(n(state.gameQuizIndex)%Math.max(1,rows.length)+1)+' in the selected snapshot · price '+esc(target.price||"unavailable")+' · 24h '+change(target.change)+'.</p><div class="game-choice-grid">'+choices+'</div>'+result+'<div class="game-native-actions"><button class="primary" data-action="next-quiz">Next sourced clue</button><button class="ghost" data-action="refresh">Refresh snapshot</button></div></main>')}
