    function applyLiveData(data){var status=document.getElementById("liveStatus");dataProvider=String(data&&data.provider||"unverified").trim().toLowerCase();dataAdapterCompleted=Boolean(Array.isArray(data.coins)&&data.coins.length);if(dataAdapterCompleted)market=data.coins;if(Array.isArray(data.events)&&data.events.length)prediction=data.events[0];unlocks=Array.isArray(data&&data.unlocks)?data.unlocks:[];funding=Array.isArray(data&&data.funding)?data.funding:[];activities=Array.isArray(data&&data.activities)?data.activities:[];var nextCapabilities=data&&data.capabilities&&typeof data.capabilities==="object"?data.capabilities:{};capabilities={coins:dataProvider==="dropstab"&&Boolean(nextCapabilities.coins),unlocks:dataProvider==="dropstab"&&Boolean(nextCapabilities.unlocks),funding:dataProvider==="dropstab"&&Boolean(nextCapabilities.funding),activities:dataProvider==="dropstab"&&Boolean(nextCapabilities.activities)};document.getElementById("sourceLabel").textContent=dataProvider==="dropstab"?(data.source||"Live DropsTab data"):"Live prices ready · connect DropsTab for unlocks, funding and activity";if(status)status.textContent=dataAdapterCompleted&&dataProvider==="dropstab"?"LIVE DROPSTAB":"SNAPSHOT";if(!(spec.presetId==="crypto-game"&&state.gameActive))render();else reportRuntimeSmoke()}
