    function syncCatcherFrame(){var game=document.querySelector(".catcher-runtime");if(!game)return;var stats=game.querySelectorAll(".hud-stat strong");if(stats[0])stats[0].textContent=n(state.score).toLocaleString();if(stats[1])stats[1].innerHTML=Array.from({length:Math.max(0,n(state.gameLives))}).map(function(){return "<i></i>"}).join("")||"—";var timerNode=document.getElementById("roundTimer");if(timerNode)timerNode.textContent=n(state.gameSeconds)+"s";var player=game.querySelector(".catcher-player");if(player)player.style.left=(12.5+n(state.gameLane)*25)+"%";var object=game.querySelector(".drop-object");if(!object)return;object.classList.toggle("hazard",Boolean(state.gameHazard));object.style.setProperty("--lane",(13+n(state.gameDropLane)*24)+"%");object.textContent=state.gameHazard?"!":String(((gameMarket()[n(state.gameDropLane)%Math.max(1,gameMarket().length)]||{}).symbol)||"BTC");object.style.animation="none";void object.offsetWidth;object.style.animation=""}
    function startCatcher(){clearInterval(timer);state.score=0;state.gameLives=3;state.gameSeconds=n((spec.gameDirection||{}).roundSeconds)||30;state.gameActive=true;state.gameDropLane=Math.floor(Math.random()*4);state.gameHazard=Math.random()<.24;state.lastResult="";save();rerenderGame();timer=setInterval(function(){state.gameSeconds-=1;var caught=n(state.gameLane)===n(state.gameDropLane);if(caught){if(state.gameHazard){state.gameLives=Math.max(0,n(state.gameLives)-1);notify("Unlock hazard caught — one life lost")}else{var coin=market[n(state.gameDropLane)%Math.max(1,market.length)]||{};state.score+=20+Math.max(0,Math.round(n(coin.change)));state.streak+=1}}else if(!state.gameHazard){state.streak=0}state.gameDropLane=Math.floor(Math.random()*4);state.gameHazard=Math.random()<.24;if(state.gameSeconds<=0||state.gameLives<=0){clearInterval(timer);state.gameActive=false;state.gameSeconds=0;state.rounds+=1;state.lastResult=state.gameLives<=0?"Three unlock hazards ended the round":"Timer finished — challenge complete";save();rerenderGame();return}save();syncCatcherFrame()},1000)}
    function customAction(button){if(spec.presetId!=="custom-product")return false;var screenId=button.dataset.customScreen;if(screenId){if((customGraph.screens||[]).some(function(screen){return screen.id===screenId})){state.customScreen=screenId;save();renderCustomProduct()}return true}var action=button.dataset.customAction;if(!action)return false;var symbol=String(button.dataset.customSymbol||"");if(action==="favorite"){state.favorites=state.favorites.indexOf(symbol)>=0?state.favorites.filter(function(item){return item!==symbol}):state.favorites.concat(symbol).slice(-40);save();renderCustomProduct();return true}if(action==="compare"){state.customCompare=state.customCompare.indexOf(symbol)>=0?state.customCompare.filter(function(item){return item!==symbol}):state.customCompare.concat(symbol).slice(-3);save();renderCustomProduct();return true}if(action==="save-local"){var notes=document.getElementById("customNotes");var portfolio=document.getElementById("customPortfolio");if(notes)state.customNotes=String(notes.value||"").slice(0,4000);if(portfolio)state.customPortfolio=String(portfolio.value||"").slice(0,500);state.customSavedAt=new Date().toISOString();save();notify("Saved in this browser");renderCustomProduct();return true}if(action==="filter"){var search=document.getElementById("customMarketSearch");if(search)search.focus();return true}if(action==="sort"){state.customSort=state.customSort==="gainers"?"name":"gainers";save();renderCustomProduct();return true}if(action==="refresh"){refreshData();return true}if(action==="open-dropstab"){dropstab();return true}if(action==="configure-dropsbot"){dropsbotSetup(button);return true}return action==="none"}
    function safeCopyAction(button,action){if(spec.presetId!=="smart-money-copy"||action!=="paper-copy")return false;var execution=String(button.dataset.executionMode||spec.values.execute||"Paper trade");if(spec.values.size==="Alert only"||execution==="Telegram alert"){dropsbotSetup(button);return true}if(execution==="Research only"){dropstab();return true}if(execution==="Approval plan"){state.paperTrades=[{time:new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}),asset:"Approval plan · "+String(spec.values.confirm||"context review")}].concat(state.paperTrades||[]).slice(0,8);save();notify("Approval plan saved locally — nothing executed");render();return true}return false}
